use std::process::Command;
fn main(){
    // xorshift rng
    let mut st: u64 = 0x12345678deadbeef;
    let mut rnd = move || { st^=st<<13; st^=st>>7; st^=st<<17; st };
    let mut bad = 0usize; let mut n = 0usize;
    // pools: full byte range minus NUL
    for trial in 0..6000 {
        let len = match trial % 4 {
            0 => (rnd() % 300 + 1) as usize,
            1 => { let c=[1usize,2,62,63,64,127,128,253,254,255,256,257,258,300,511,512]; c[(rnd() as usize)%16] }
            2 => (rnd() % 8 + 250) as usize,
            _ => (rnd() % 20 + 1) as usize,
        };
        let mode = rnd() % 5;
        let mut v: Vec<u8> = Vec::with_capacity(len);
        for _ in 0..len {
            let b = match mode {
                0 => (rnd() % 255 + 1) as u8,                 // any non-NUL byte
                1 => (rnd() % 128) as u8 | 1,                 // ascii
                2 => (rnd() % 128 + 128) as u8,               // high bytes only
                3 => { let p=b"abcXYZ.-_ /*@!#\t\r\n"; p[(rnd() as usize)%p.len()] }
                _ => { let p=b".ab"; p[(rnd() as usize)%p.len()] }
            };
            v.push(if b==0 {b'a'} else {b});
        }
        let s = unsafe { std::ffi::OsString::from(std::os::unix::ffi::OsStringExt::from_vec(v.clone())) };
        let out = Command::new("/workspace/dataset/test4_executable").arg(&s).output().unwrap();
        let so = String::from_utf8_lossy(&out.stdout);
        let l1 = so.lines().next().unwrap_or("?").to_string();
        let pred = if v.len()>=1 && v.len()<=255 {"1"} else {"0"};
        n+=1;
        if l1 != pred {
            bad+=1;
            if bad<=10 {
                println!("MISMATCH len={} mode={} pred={} got={} first40={:?}", v.len(), mode, pred, l1, &v[..v.len().min(40)]);
            }
        }
    }
    println!("tested={} mismatches={}", n, bad);
}
EOF
